# =============================================================================
# Chapter 11 values: Factor Analysis
#
# Run from the project root:
#   Rscript r_code/figures/chapter_11_values.R
#
# The figures are generated by r_code/figures/chapter_11.R. This script records
# the values behind the prose and Tables 11.1 through 11.4. All analyses use
# speed_dating.csv. The author's original calculations are in
# r_code/chapter_11.r; this script reproduces them with psych and records the
# conventions. figures/chapter_11/values.yml is generated by
# save_book_values(); do not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
  library(psych)
})

# ---- Data -------------------------------------------------------------------

df <- read_csv("data/speed_dating.csv", show_col_types = FALSE)

vars_f <- c(
  "AttractiveF", "SincereF", "IntelligentF",
  "FunF", "AmbitiousF", "SharedInterestsF"
)
vars_m <- c(
  "AttractiveM", "SincereM", "IntelligentM",
  "FunM", "AmbitiousM", "SharedInterestsM"
)

data_f <- df %>%
  select(all_of(vars_f)) %>%
  filter(if_all(everything(), ~ !is.na(.x)))
data_m <- df %>%
  select(all_of(vars_m)) %>%
  filter(if_all(everything(), ~ !is.na(.x)))

cor_f <- cor(data_f)
cor_m <- cor(data_m)

# ---- Models -----------------------------------------------------------------

paf_f <- fa(data_f, nfactors = 2, fm = "pa", rotate = "varimax")
ml_f <- fa(data_f, nfactors = 2, fm = "ml", rotate = "varimax")
pca_f <- principal(data_f, nfactors = 2, rotate = "varimax")

# The male two-factor PAF solution does not converge. psych prints
# "maximum iteration exceeded" to the console rather than raising a warning,
# so the condition is recorded in the registry by hand.
paf_m <- fa(data_m, nfactors = 2, fm = "pa", rotate = "varimax")

# ---- Scree values -----------------------------------------------------------

scree_values <- round(eigen(cor_f)$values, 3)

# ---- Cronbach's alpha -------------------------------------------------------

alpha_value <- function(items) {
  suppressWarnings(suppressMessages(
    psych::alpha(items, check.keys = FALSE)$total$raw_alpha
  ))
}

alpha_level <- alpha_value(data_f[, c("IntelligentF", "AmbitiousF", "SincereF")])
alpha_appeal <- alpha_value(data_f[, c("AttractiveF", "FunF", "SharedInterestsF")])
alpha_f_all <- alpha_value(data_f)
alpha_m_all <- alpha_value(data_m)

# ---- Helpers ----------------------------------------------------------------

loading_table <- function(fit, prefix) {
  loads <- unclass(fit$loadings)
  out <- data.frame(
    variable = rownames(loads), check.names = FALSE, row.names = NULL
  )
  for (j in seq_len(ncol(loads))) {
    out[[paste0(prefix, "_", j)]] <- round(loads[, j], 3)
  }
  out
}

cor_table <- function(m) {
  out <- data.frame(
    variable = rownames(m), round(m, 3),
    check.names = FALSE, row.names = NULL
  )
  names(out) <- c("variable", colnames(m))
  out
}

