# ---- Console summary --------------------------------------------------------

cat("\n--- Chapter 11 summary ---\n")
cat("Rows:", nrow(df), " female complete:", nrow(data_f),
    " male complete:", nrow(data_m), "\n")
cat("PAF F loadings:\n"); print(round(unclass(paf_f$loadings), 3))
cat("PAF F communalities:", round(paf_f$communality, 3), "\n")
cat("PAF F proportion var:", round(paf_f$Vaccounted["Proportion Var", ], 3),
    "\n")
cat("ML F IntelligentF:", round(unclass(ml_f$loadings)["IntelligentF", 1], 3),
    "\n")
cat("PCA F loadings:\n"); print(round(unclass(pca_f$loadings), 3))
cat("Initial eigenvalues:", scree_values, "\n")
